{
    "openapi": "3.1.0",
    "info": {
        "title": "Katalyst",
        "summary": "Turns a plain-English hypothesis into a cause-and-effect map that ends in trades.",
        "description": "The routes the Katalyst browser app calls. The description of this API is generated from the data shapes the program itself uses, and the browser app's TypeScript types are generated from this description, so the two halves cannot drift apart without a build failing.",
        "version": "0.1.0"
    },
    "paths": {
        "/api/healthz": {
            "get": {
                "tags": [
                    "health"
                ],
                "summary": "Healthz",
                "description": "Report that the program is running.\n\nThis answer depends on nothing: no key, no database, no other service. That\nis the point. A container manager restarts the program when this route stops\nanswering, so anything it depended on could cause restarts for a reason that\nhas nothing to do with the program being alive.\n\nReturns:\n    A fixed status of \"ok\".",
                "operationId": "healthz_api_healthz_get",
                "responses": {
                    "200": {
                        "description": "Successful Response",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Health"
                                }
                            }
                        }
                    }
                }
            }
        },
        "/api/readyz": {
            "get": {
                "tags": [
                    "health"
                ],
                "summary": "Readyz",
                "description": "Report whether the program can generate a map yet.\n\nToday that comes down to one thing: whether a key for the language model is\nconfigured. Without it the program still runs, still serves the stored\nexample map, and still says so honestly here rather than failing later with\nan error the user cannot interpret.\n\nArgs:\n    settings: The program's settings. Supplied by the web framework, which\n        lets a test replace them without touching the real environment.\n\nReturns:\n    Whether the program is ready, and whether a model key is configured.",
                "operationId": "readyz_api_readyz_get",
                "responses": {
                    "200": {
                        "description": "Successful Response",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Readiness"
                                }
                            }
                        }
                    }
                }
            }
        },
        "/api/about": {
            "get": {
                "tags": [
                    "about"
                ],
                "summary": "About",
                "description": "Report the product name and the running version.\n\nReturns:\n    The name and the version of this build.",
                "operationId": "about_api_about_get",
                "responses": {
                    "200": {
                        "description": "Successful Response",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/About"
                                }
                            }
                        }
                    }
                }
            }
        }
    },
    "components": {
        "schemas": {
            "About": {
                "properties": {
                    "name": {
                        "type": "string",
                        "title": "Name",
                        "description": "The product name, always \"Katalyst\"."
                    },
                    "version": {
                        "type": "string",
                        "title": "Version",
                        "description": "The version of the running build, such as 0.1.0."
                    }
                },
                "type": "object",
                "required": [
                    "name",
                    "version"
                ],
                "title": "About",
                "description": "What this program calls itself, and which build is running."
            },
            "Health": {

