input.content:
/*
 * The styles for the one screen this app currently has.
 *
 * Every value here comes from a token in `tokens.css`; there are no raw colours
 * and no raw pixel sizes below. If a number looks arbitrary it is a mistake.
 *
 * The screen is a single left-aligned column: the product name, one line saying
 * what the tool does, and a quiet strip of three rows reporting what the server
 * just told us. No cards with shadows, no buttons that do nothing, no
 * decoration. Density here follows the rule that there should be nothing
 * between the reader and the data.
 */

/* ---- Base ------------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-interface);
  font-size: var(--text-md);
  font-weight: var(--weight-regular);
  line-height: 1.55;
  /* Fixed-width digits everywhere, so a number that changes never shifts the
   * text beside it (UX-11). */
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

/* The keyboard ring. It is drawn on anything focusable, and it is drawn the
 * same way everywhere so it is never a surprise (UX-9, UX-12). */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ---- The page --------------------------------------------------------- */

.page {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: var(--space-6) var(--space-3);
}

