1	/**
2	 * The whole screen, for now.
3	 *
4	 * It names the product, says in one line what the product does, and reports
5	 * what the server just told us about itself. That report is the interesting
6	 * part: three readings, each one traceable to the route it came from, each one
7	 * in one of exactly three named states — waiting for an answer, answered, or
8	 * failed. There is no fourth state, and nothing on the screen is drawn from
9	 * anything but those three.
10	 *
11	 * Which product rules this serves (PRODUCT_REQUIREMENTS.md section 7):
12	 *
13	 *   UX-6  Meaning is never carried by colour alone: every reading has a glyph
14	 *         and a word beside it, and the word is what says what happened.
15	 *   UX-7  While a request is in flight the value cell holds a plain bar of the
16	 *         same height, so nothing moves when the answer lands. There is no
17	 *         spinner: a spinner says "wait" without saying what for.
18	 *   UX-10 A failure is printed in the row it belongs to, in a sentence. It is
19	 *         never a pop-up dialog the reader has to dismiss.
20	 *   UX-11 Values sit in the monospace face with fixed-width digits.
21	 *   UX-12 The readings are a description list, so the relationship between a
22	 *         label and its value survives being read aloud.
23	 */
24	
25	import { useEffect, useState } from "react";
26	import type { About, Health, Readiness } from "./api/client";
27	import { readAbout, readHealth, readReadiness } from "./api/client";
28	
29	/**
30	 * Everything the screen can know about one reading. There are three states and
31	 * no others, which is what makes every pixel below traceable to a cause.
32	 */
33	type Answer<Reading> =
34	  | { state: "asking" }
35	  | { state: "answered"; value: Reading }
36	  | { state: "failed"; reason: string };
37	
38	/**
39	 * How loud a row's words are. This changes emphasis only — the words carry the
40	 * meaning, so a reader who cannot see the difference loses nothing.
41	 */
42	type Tone = "good" | "quiet" | "loud";
43	
44	/** One row of the strip, already turned into the words that will be printed. */
45	type Reading = {
46	  /** What is being reported, such as "server". */
47	  label: string;
48	  /** The value from the server, or null while the request is still in flight. */
49	  value: string | null;
50	  /** A mark beside the words. Never the only carrier of meaning. */
51	  glyph: string;
52	  /** What the value means, in plain words. On a failure, this is the failure. */
53	  state: string;
54	  tone: Tone;
55	};
56	
57	/** Turn whatever a failed request threw into one sentence. */
58	function inWords(reason: unknown): string {
59	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
60	}
61	
62	/**
63	 * Make one request when the screen first appears and report where it got to.
64	 *
65	 * @param ask The request to make. It must be the same function on every render,
66	 *   so pass one defined at module level rather than one written inline.
67	 */
68	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
69	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
70	
71	  useEffect(() => {
72	    let stillOnScreen = true;
73	    ask().then(
74	      (value) => {
75	        if (stillOnScreen) {
76	          setAnswer({ state: "answered", value });
77	        }
78	      },
79	      (reason: unknown) => {
80	        if (stillOnScreen) {
81	          setAnswer({ state: "failed", reason: inWords(reason) });
82	        }
83	      },
84	    );
85	    return () => {
86	      stillOnScreen = false;
87	    };
88	  }, [ask]);
89	
90	  return answer;
91	}
92	
93	/** The row that says whether the server answered at all. */
94	function serverReading(answer: Answer<Health>): Reading {
95	  switch (answer.state) {
96	    case "asking":
97	      return {
98	        label: "server",
99	        value: null,
100	        glyph: "○",
101	        state: "asking the server",
102	        tone: "quiet",
103	      };
104	    case "answered":
105	      return {
106	        label: "server",
107	        value: answer.value.status,
108	        glyph: "●",
109	        state: "reachable",
110	        tone: "good",
111	      };
112	    case "failed":
113	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
114	  }
115	}
116	
117	/** The row that says whether a key for the language model is configured. */
118	function modelKeyReading(answer: Answer<Readiness>): Reading {
119	  switch (answer.state) {
120	    case "asking":
121	      return {
122	        label: "model key",
123	        value: null,
124	        glyph: "○",
125	        state: "asking the server",
126	        tone: "quiet",
127	      };
128	    case "answered":
129	      return answer.value.model_key_present
130	        ? {
131	            label: "model key",
132	            value: "present",
133	            glyph: "●",
134	            state: "ready to generate",
135	            tone: "good",
136	          }
137	        : {
138	            label: "model key",
139	            value: "absent",
140	            glyph: "○",
141	            state: "no key configured — generation arrives in stack 04",
142	            tone: "quiet",
143	          };
144	    case "failed":
145	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
146	  }
147	}
148	
149	/** The row that says which build answered. */
150	function versionReading(answer: Answer<About>): Reading {
151	  switch (answer.state) {
152	    case "asking":
153	      return {
154	        label: "version",
155	        value: null,
156	        glyph: "○",
157	        state: "asking the server",
158	        tone: "quiet",
159	      };
160	    case "answered":
161	      return {
162	        label: "version",
163	        value: answer.value.version,
164	        glyph: "●",
165	        state: `named ${answer.value.name}`,
166	        tone: "good",
167	      };
168	    case "failed":
169	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
170	  }
171	}
172	
173	/**
174	 * One row: a label, the value the server gave, and what that value means.
175	 *
176	 * While the value is missing the cell holds a bar of the same height, so the
177	 * row does not change size when the answer arrives. Once there is a value the
178	 * cell fades it in over a single duration token and then stops moving.
179	 */
180	function StatusRow({ reading }: { reading: Reading }) {
181	  const waiting = reading.value === null;
182	  return (
183	    <div className="status-row">
184	      <dt className="status-label">{reading.label}</dt>
185	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
186	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
187	      </dd>
188	      <dd className="status-state" data-tone={reading.tone}>
189	        <span className="glyph" aria-hidden="true">
190	          {reading.glyph}
191	        </span>
192	        <span className="state-words">{reading.state}</span>
193	      </dd>
194	    </div>
195	  );
196	}
197	
198	/** The screen. */
199	export function App() {
200	  const health = useAnswer(readHealth);
201	  const readiness = useAnswer(readReadiness);
202	  const about = useAnswer(readAbout);
203	
204	  const readings = [serverReading(health), modelKeyReading(readiness), versionReading(about)];
205	
206	  return (
207	    <main className="page">
208	      <div className="column">
209	        <header className="masthead">
210	          <h1 className="wordmark">Katalyst</h1>
211	          <p className="purpose">
212	            Type an event you think will happen. See what it would cause, step by step, ending in
213	            trades.
214	          </p>
215	        </header>
216	
217	        <section aria-labelledby="status-heading">
218	          <h2 className="section-heading" id="status-heading">
219	            What this build can do right now
220	          </h2>
221	          <dl className="status-strip">
222	            {readings.map((reading) => (

