1	/*
2	 * The design tokens for Katalyst.
3	 *
4	 * This file is the whole visual vocabulary of the product in one place: every
5	 * colour, size, weight, space and duration the interface is allowed to use.
6	 * Nothing else in the app writes a raw colour or a raw pixel number. Later work
7	 * — the workbench canvas with its proposition tiles and causal wires — inherits
8	 * these same names, so the first screen and the finished product cannot drift
9	 * apart visually.
10	 *
11	 * Which product rules this serves (from PRODUCT_REQUIREMENTS.md section 7):
12	 *
13	 *   UX-6  "Colour is law."  Direction of financial effect is blue for up and
14	 *         amber for down, never red and green, and always carried by a glyph
15	 *         and a word as well as a hue. Tail risk (a rare, large outcome) is a
16	 *         hatched texture rather than a colour, because texture survives every
17	 *         kind of colour blindness and survives inverting light and dark.
18	 *   UX-7  "Motion budget."  On this screen there is exactly one animation: a
19	 *         placeholder fading into the value that replaced it. One duration
20	 *         token controls it, and it becomes instant when the operating system
21	 *         asks for reduced motion.
22	 *   UX-11 "Typography."  One interface typeface, one monospace typeface with
23	 *         fixed-width digits for every number, exactly three sizes and exactly
24	 *         three weights. Hierarchy comes from colour and spacing, not size.
25	 *   UX-12 "Themes and access."  Dark is the default; a light theme is defined
26	 *         too. Every piece of text clears a contrast ratio of 4.5 to 1 against
27	 *         the surface behind it, in both themes. The ratios are written beside
28	 *         each colour below.
29	 *
30	 * How the two themes are chosen:
31	 *   - The page ships dark, because `index.html` sets `data-theme="dark"` on the
32	 *     html element. That attribute wins over everything else.
33	 *   - `data-theme="light"` forces the light theme.
34	 *   - Remove the attribute and the page follows the operating system: dark
35	 *     unless the operating system asks for light.
36	 */
37	
38	:root {
39	  /* ---- Typefaces ------------------------------------------------------ *
40	   * Inter for the interface and JetBrains Mono for every number.
41	   *
42	   * Why this pair, and not Geist: both are shipped as ordinary npm packages
43	   * (`@fontsource-variable/...`) that carry the font files themselves, so the
44	   * app draws its first frame with no request to any outside service and works
45	   * with no network at all inside a container. The `geist` package publishes
46	   * its fonts only through the Next.js font loader, which this app does not
47	   * use. Inter is a neutral interface face that stays legible at 13 pixels;
48	   * JetBrains Mono has fixed-width digits, so a number that changes does not
49	   * make the column beside it jump sideways.
50	   *
51	   * The system fallbacks after each name are what a browser draws in the
52	   * fraction of a second before the font file arrives. */
53	  --font-interface:
54	    "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
55	  --font-mono: "JetBrains Mono Variable", ui-monospace, "SF Mono", "Cascadia Mono", monospace;
56	
57	  /* ---- Type scale: exactly three sizes, exactly three weights --------- *
58	   * 13 / 15 / 22 pixels. A fourth size is not a small addition; it is a new
59	   * rule everything afterwards has to obey, so there are three. */
60	  --text-sm: 13px;
61	  --text-md: 15px;
62	  --text-lg: 22px;
63	
64	  --weight-regular: 400;
65	  --weight-medium: 500;
66	  --weight-semibold: 600;
67	
68	  /* ---- Spacing: an eight-pixel grid ----------------------------------- *
69	   * Every margin, padding and gap is one of these. `--space-hair` is the one
70	   * half-step, for the gap between a glyph and the word beside it. */
71	  --space-hair: 4px;
72	  --space-1: 8px;
73	  --space-2: 16px;
74	  --space-3: 24px;
75	  --space-4: 32px;
76	  --space-5: 48px;
77	  --space-6: 64px;
78	
79	  --radius: 6px;
80	
81	  /* ---- Motion --------------------------------------------------------- *
82	   * One duration, used only for opacity. Nothing here moves position, scales,
83	   * bounces or loops. */
84	  --duration-fast: 120ms;
85	
86	  /* ---- Dark theme: the default ---------------------------------------- *
87	   * Contrast ratios below are measured against `--surface` (#0E1116), whose
88	   * own ratio against white is 18.9 to 1. It is a very dark blue-grey rather
89	   * than pure black: pure black against bright text vibrates at small sizes,
90	   * and leaves no darker shade to fall back on. */
91	  color-scheme: dark;
92	
93	  --surface: #0e1116;
