1	/*
2	 * The styles for the one screen this app currently has.
3	 *
4	 * Every value here comes from a token in `tokens.css`; there are no raw colours
5	 * and no raw pixel sizes below. If a number looks arbitrary it is a mistake.
6	 *
7	 * The screen is a single left-aligned column: the product name, one line saying
8	 * what the tool does, and a quiet strip of three rows reporting what the server
9	 * just told us. No cards with shadows, no buttons that do nothing, no
10	 * decoration. Density here follows the rule that there should be nothing
11	 * between the reader and the data.
12	 */
13	
14	/* ---- Base ------------------------------------------------------------- */
15	
16	*,
17	*::before,
18	*::after {
19	  box-sizing: border-box;
20	}
21	
22	html,
23	body {
24	  margin: 0;
25	  padding: 0;
26	}
27	
28	body {
29	  background: var(--surface);
30	  color: var(--text);
31	  font-family: var(--font-interface);
32	  font-size: var(--text-md);
33	  font-weight: var(--weight-regular);
34	  line-height: 1.55;
35	  /* Fixed-width digits everywhere, so a number that changes never shifts the
36	   * text beside it (UX-11). */
37	  font-variant-numeric: tabular-nums;
38	  -webkit-font-smoothing: antialiased;
39	}
40	
41	/* The keyboard ring. It is drawn on anything focusable, and it is drawn the
42	 * same way everywhere so it is never a surprise (UX-9, UX-12). */
43	:focus-visible {
44	  outline: 2px solid var(--focus);
45	  outline-offset: 2px;
46	  border-radius: 2px;
47	}
48	
49	/* ---- The page --------------------------------------------------------- */
50	
51	.page {
52	  min-height: 100vh;
53	  display: flex;
54	  align-items: flex-start;
55	  justify-content: center;
56	  padding: var(--space-6) var(--space-3);
57	}
58	
59	.column {
60	  width: 100%;
61	  max-width: 660px;
62	}
63	
64	/* ---- Masthead: the product name and the one line under it ------------- */
65	
66	.masthead {
67	  margin-bottom: var(--space-5);
68	}
69	
70	.wordmark {
71	  margin: 0;
72	  font-size: var(--text-lg);
73	  font-weight: var(--weight-semibold);
74	  letter-spacing: -0.015em;
75	  line-height: 1.2;
76	  color: var(--text);
77	}
78	
79	.purpose {
80	  margin: var(--space-1) 0 0;
81	  max-width: 46ch;
82	  font-size: var(--text-md);
83	  font-weight: var(--weight-regular);
84	  color: var(--text-muted);
85	}
86	
87	.section-heading {
88	  margin: 0 0 var(--space-1);
89	  font-size: var(--text-sm);
90	  font-weight: var(--weight-medium);
91	  letter-spacing: 0.02em;
92	  color: var(--text-muted);
93	}
94	
95	/* ---- The status strip -------------------------------------------------- *
96	 * Three rows, each one answer from the server. A description list is the right
97	 * shape for it: each row has one term (what is being reported) and two details
98	 * (the value, and what that value means in words). */
99	
100	.status-strip {
101	  margin: 0;
102	  padding: var(--space-1) var(--space-2);
103	  background: var(--surface-raised);
104	  border: 1px solid var(--hairline);
105	  border-radius: var(--radius);
106	}
107	
108	.status-row {
109	  display: grid;
110	  grid-template-columns: 7rem 7rem minmax(0, 1fr);
111	  gap: var(--space-2);
112	  align-items: baseline;
113	  padding: var(--space-1) 0;
114	}
115	
116	.status-row + .status-row {
117	  border-top: 1px solid var(--hairline);
118	}
119	
120	/* Narrow screens: the three columns stack rather than squeeze. */
121	@media (width < 560px) {
122	  .status-row {
123	    grid-template-columns: minmax(0, 1fr);
124	    gap: var(--space-hair);
125	  }
126	}
127	
128	.status-label {
129	  margin: 0;
130	  font-size: var(--text-sm);
131	  font-weight: var(--weight-medium);
132	  color: var(--text-muted);
133	}
134	
135	/* The value cell. This is the only place a value from the server is printed,
136	 * and it is the class that puts it in the monospace face with fixed-width
137	 * digits (UX-11). The test `the version reads in the monospace face` checks
138	 * for this class by name. */
139	.status-value {
140	  margin: 0;
141	  font-family: var(--font-mono);
142	  font-variant-numeric: tabular-nums;
143	  font-size: var(--text-sm);
144	  font-weight: var(--weight-medium);
145	  color: var(--text);
146	}
147	
148	/* The value has just replaced its placeholder: fade it in over one duration
149	 * token, and nothing else. Under reduced motion the token is 0ms, so the value
150	 * simply appears (UX-7). */
151	.status-value[data-settled="yes"] {
152	  animation: value-arrives var(--duration-fast) ease-out;
153	}
154	
155	@keyframes value-arrives {
156	  from {
157	    opacity: 0;
158	  }
159	  to {
160	    opacity: 1;
161	  }
162	}
163	
164	/* While the request is in flight the value cell holds a bar of the same height
165	 * where the value will land, so nothing moves when the answer arrives. It is
166	 * not a spinner and it does not pulse: a spinner says "wait" without saying
167	 * what for, and this page always says what for in the cell beside it. */
168	.placeholder {
169	  display: inline-block;
170	  width: 4.5ch;
171	  height: 0.85em;
172	  vertical-align: -0.05em;
173	  border-radius: 2px;
174	  background: var(--hairline);
175	}
176	
177	.status-state {
178	  margin: 0;
179	  font-size: var(--text-sm);
180	  color: var(--text-muted);
181	}
182	
183	/* The state cell reads as a glyph and then a word, never a colour on its own
184	 * (UX-6, and invariant INV-12: nothing is encoded in hue alone). The three
185	 * tones below change how loud the row is, not what it means — the words carry
186	 * the meaning. */
187	.glyph {
188	  margin-right: var(--space-hair);
189	}
190	
191	.status-state[data-tone="good"] .glyph {
192	  color: var(--accent);
193	}
194	
195	.status-state[data-tone="quiet"] .glyph {
196	  color: var(--text-muted);
197	}
198	
199	.status-state[data-tone="loud"] {
200	  color: var(--text);
201	}
202	
203	.status-state[data-tone="loud"] .glyph {
204	  color: var(--text);
205	}
206	
207	
208	/* ---- The footnote ------------------------------------------------------ *
209	 * Names the three addresses the three rows were read from, so every value on
210	 * this screen can be traced back to where it came from without opening the
211	 * code. */
212	
213	.provenance {
214	  margin: var(--space-2) 0 0;
215	  font-size: var(--text-sm);
216	  color: var(--text-muted);
217	}
218	
219	.provenance code {
220	  font-family: var(--font-mono);
221	  font-size: var(--text-sm);
222	  color: var(--text-muted);
223	}

